create table if not exists public.curated_operation_pattern_rules (id bigint generated by default as identity primary key, network_key text not null, effective_from date not null, operation_code_pattern text not null, owner_operator text not null, vehicle_type text, source_url text not null, evidence_grade text not null default 'C', source_path text not null, notes text, created_at timestamptz not null default now(), constraint curated_operation_pattern_rules_unique unique(network_key,effective_from,operation_code_pattern)); alter table public.curated_operation_pattern_rules enable row level security; comment on table public.curated_operation_pattern_rules is 'Curated non-API operation-code structural ownership patterns, not realtime or train timetable API data.';
